/* stack.h */
typedef struct Stack Stack;   /* opaque: no fields shown */
Stack *stack_new(void);
int    stack_push(Stack *s, int x);
int    stack_pop(Stack *s, int *out);

/* stack.c */
struct Stack { int data[100]; int top; };  /* hidden */

function sum(n: number): number {
	if (n === 0) return 0;      // base case: nothing left to add
	return n + sum(n - 1);      // step: a smaller problem
}
